/**
 * hna-chapter-handoff.js — fill in "What you have now" at the end of each part.
 *
 * The markup is generated by scripts/hna/build_hna_views.py with every figure
 * hidden. This copies the values out of the stat cells already on the page and
 * reveals only the ones that actually arrived.
 *
 * WHY IT COPIES RATHER THAN COMPUTES
 *
 * A summary that re-derives its own numbers is a second producer, and this
 * repo has spent a week on what that costs — co-county-demographics.json had
 * two producers disagreeing daily, both green. If the handoff said something
 * the panel above it did not, the reader would have no way to tell which was
 * right. So it quotes.
 *
 * ABSENCE
 *
 * A stat that never loaded reads as "—" in its card. Repeating that here would
 * be the same defect one more time: a dash looks like an answer. A figure that
 * is missing, dashed, or still a placeholder is dropped, and if none survive
 * the block says so plainly instead of showing an empty list under a heading
 * promising a summary.
 */
(function () {
  'use strict';

  var PLACEHOLDER = /^(|—|–|-|\.\.\.|…|Loading|Unavailable|N\/A|n\/a)$/i;

  function usable(text) {
    if (typeof text !== 'string') return false;
    var t = text.trim();
    if (PLACEHOLDER.test(t)) return false;
    // Must carry at least one digit: "Tenure" style labels and error strings
    // are not figures, and a summary of them would say nothing.
    return /\d/.test(t);
  }

  function fill() {
    var host = document.getElementById('hnaChapterHandoff');
    if (!host) return 0;
    var items = host.querySelectorAll('li[data-stat]');
    var shown = 0;
    for (var i = 0; i < items.length; i++) {
      var li = items[i];
      var src = document.getElementById(li.getAttribute('data-stat'));
      var value = src ? src.textContent : null;
      if (!usable(value)) { li.hidden = true; continue; }
      var slot = li.querySelector('.hna-handoff__n');
      if (slot) slot.textContent = value.trim();
      li.hidden = false;
      shown += 1;
    }
    var empty = host.querySelector('.hna-handoff__empty');
    var list = host.querySelector('.hna-handoff__list');
    if (empty) empty.hidden = shown > 0;
    if (list) list.hidden = shown === 0;
    return shown;
  }

  function start() {
    // The stat cells fill after data loads, and some arrive late. Re-run on
    // mutation rather than guessing a delay — the glossary learned the same
    // lesson: a single pass at load time sees only the empty shell.
    fill();
    var host = document.getElementById('hnaChapterHandoff');
    if (!host || typeof MutationObserver !== 'function') return;
    var main = document.querySelector('main') || document.body;
    var pending = null;
    var busy = false;
    new MutationObserver(function () {
      if (busy) return;
      if (pending) clearTimeout(pending);
      pending = setTimeout(function () {
        pending = null;
        busy = true;
        try { fill(); } catch (e) { /* never break the page for a summary */ }
        finally { setTimeout(function () { busy = false; }, 0); }
      }, 350);
    }).observe(main, { childList: true, subtree: true, characterData: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }

  window.HNAChapterHandoff = { fill: fill };
})();
